import { safeVaultPath } from './knowledge';

/** Marker used to identify indexes generated by the integration. */
export const DATAVIEW_INDEX_MARKER = '<!-- independent-rss-reader:dataview-index -->';
export const DEFAULT_DATAVIEW_INDEX_TITLE = 'RSS 文章索引';
export const DEFAULT_DATAVIEW_INDEX_PATH = 'RSS Articles/RSS Articles Index.md';

export type DataviewIndexField = 'article' | 'source' | 'published' | 'tags' | 'path';

export interface DataviewIndexOptions {
  /** Vault-relative folder containing saved RSS article Markdown files. */
  saveFolder: string;
  /** Heading used for the generated index. */
  title?: string;
  /** Columns to render, in order. Unknown fields are rejected. */
  fields?: readonly DataviewIndexField[];
}

export const DEFAULT_DATAVIEW_INDEX_FIELDS: readonly DataviewIndexField[] = [
  'article',
  'source',
  'published',
  'tags',
];

const FIELD_DEFINITIONS: Readonly<Record<DataviewIndexField, { expression: string; label: string }>> = {
  article: { expression: 'file.link', label: '文章' },
  source: { expression: 'source', label: '来源' },
  published: { expression: 'published', label: '发布时间' },
  tags: { expression: 'tags', label: '标签' },
  path: { expression: 'file.path', label: '路径' },
};

/**
 * Normalize and validate a vault-relative folder before placing it in a
 * Dataview FROM clause. The path is deliberately validated with the same
 * rules used by article saving, so the query cannot escape the vault.
 */
export function normalizeDataviewFolder(folder: string): string {
  const candidate = folder.trim().replaceAll('\\', '/');
  if (!candidate) throw new Error('Dataview 索引目录不能为空');
  try {
    const markerPath = safeVaultPath(candidate, '__rss_dataview_index__.md');
    return markerPath.slice(0, markerPath.lastIndexOf('/')) || markerPath.replace('/__rss_dataview_index__.md', '');
  } catch {
    throw new Error('Dataview 索引目录无效');
  }
}

function normalizeTitle(title: string | undefined): string {
  const normalized = (title || DEFAULT_DATAVIEW_INDEX_TITLE).replace(/[\r\n]+/g, ' ').trim();
  return normalized || DEFAULT_DATAVIEW_INDEX_TITLE;
}

function normalizeFields(fields: readonly DataviewIndexField[] | undefined): DataviewIndexField[] {
  const requested = fields && fields.length > 0 ? fields : DEFAULT_DATAVIEW_INDEX_FIELDS;
  const unique: DataviewIndexField[] = [];
  for (const field of requested) {
    if (!Object.hasOwn(FIELD_DEFINITIONS, field)) throw new Error(`Dataview 字段无效：${String(field)}`);
    if (!unique.includes(field)) unique.push(field);
  }
  if (unique.length === 0) throw new Error('Dataview 字段不能为空');
  return unique;
}

/**
 * Render a regular Markdown note containing a Dataview query. It does not
 * depend on the Dataview plugin being installed and is safe to use while the
 * reader remains fully local: without Dataview the note is still readable as
 * ordinary Markdown and the article files remain untouched.
 */
export function renderDataviewIndex(options: DataviewIndexOptions): string {
  const folder = normalizeDataviewFolder(options.saveFolder);
  const fields = normalizeFields(options.fields);
  const title = normalizeTitle(options.title);
  const columns = fields.map(field => {
    const definition = FIELD_DEFINITIONS[field];
    return `  ${definition.expression} AS "${definition.label}"`;
  }).join(',\n');

  return `${DATAVIEW_INDEX_MARKER}

# ${title}

由本地 RSS 阅读器生成。文章仍以普通 Markdown 保存在“${folder}”目录中；安装 Dataview 后可用下方查询浏览。

\`\`\`dataview
TABLE WITHOUT ID
${columns}
FROM "${folder}"
WHERE file.path != this.file.path
SORT published DESC, file.mtime DESC
\`\`\`
`;
}
